// Define config
public class MyConfig {
    public static ForgeConfigSpec SPEC;

    // Config options
    public static ForgeConfigSpec.IntValue maxItems;
    public static ForgeConfigSpec.BooleanValue enableFeature;
    public static ForgeConfigSpec.DoubleValue speedMultiplier;
    public static ForgeConfigSpec.ConfigValue<List<String>> blockedCommands;

    static {
        ForgeConfigSpec.Builder builder = new ForgeConfigSpec.Builder();

        builder.comment("My Mod Configuration");

        maxItems = builder
            .comment("Maximum number of items")
            .defineInRange("maxItems", 64, 1, 256);

        enableFeature = builder
            .comment("Enable custom feature")
            .define("enableFeature", true);

        speedMultiplier = builder
            .comment("Speed multiplier")
            .defineInRange("speedMultiplier", 1.0, 0.1, 10.0);

        blockedCommands = builder
            .comment("List of blocked commands")
            .define("blockedCommands", Arrays.asList("kill", "stop"));

        SPEC = builder.build();
    }
}

